theme.css:
#wemd{color:#1a1a1a;background-color:#fafaf8;font-family:'Source Han Serif SC', 'Noto Serif SC', Georgia, 'Times New Roman', serif;font-size:17px;line-height:1.9;letter-spacing:0.02em;text-align:justify;padding:40px 28px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.4em;text-indent:2em}
#wemd h1{font-size:32px;font-weight:900;color:$colors.text_primary;margin-top:2.5em;margin-bottom:1.2em;text-align:left}
#wemd h2{font-size:24px;font-weight:700;color:$colors.text_primary;margin-top:2.2em;margin-bottom:1em;text-align:left;border-bottom:1px solid $colors.accent;padding-bottom:.4em}
#wemd h3{font-size:19px;font-weight:700;color:$colors.accent;margin-top:1.8em;margin-bottom:0.7em}
#wemd h4{font-size:17px;font-weight:600;color:$colors.text_secondary;margin-top:1.4em;margin-bottom:0.5em}
#wemd blockquote{border-left:5px solid $colors.quote_border;background:$colors.quote_background;padding:16px 24px;color:$colors.text_secondary;font-style:italic;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:#b91c1c;padding:2px 6px;border-radius:3px;font-size:0.88em;font-family:'Fira Code', 'JetBrains Mono', monospace}
#wemd pre{background:#2d2d2d;border-radius:4px;padding:20px 24px;line-height:1.6;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:12px 16px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:28px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:8px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px double $colors.border;margin:2.5em 0;width:60%}
#wemd img{max-width:100%;height:auto;border-radius:4px}
#wemd figcaption{font-size:14px;color:$colors.text_secondary;text-align:center}
#wemd a{color:$colors.link_color;text-decoration:underline}
#wemd strong{color:#c2410c;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 6px;border-radius:2px}
#wemd > p:first-of-type::first-letter{float:left;font-size:3.2em;color:$colors.accent;line-height:1.1;margin-right:.12em}
